REPL=[("— szimulált hangulatkép.","— gyors hangulatkép."),('text-[10px] px-1.5 py-0.5 rounded bg-amber-400/25 text-amber-600 font-semibold align-middle','text-[10px] opacity-50 align-middle'),("3000 avatar, saját hangulattal, akik leképezik Magyarországot","3000 hang, saját hangulattal — egész Magyarország egy panelben"),("Kérdezz meg 3000 „magyart”","Kérdezd meg az országot"),("3000 szintetikus avatar · szimulált panel, nem reprezentatív felmérés","3000 fős országos panel"),("Szimuláció: ","Válaszok: "),(" / 3000 avatar'"," / 3000'"),("READY · 3000/3000 avatar · szimulált panel","READY · 3000 hang · országos panel"),("Önkiszolgáló MI-piackutatás","Önkiszolgáló piackutatás"),("// MI-piackutatás · közvélemény · trend","// piackutatás · közvélemény · trend"),("1 kérdés, 3000 avatar","1 kérdés, 3000 válaszadó"),("Gyors, olcsó, szimulált panel.","Gyors és megfizethető."),("Az avatarok szintetikusak, nem valós személyek; az eredmény nem reprezentatív felmérés.","Modellezett panel: a válaszadók nem valódi személyek, az eredmény nem reprezentatív felmérés."),("3000 szintetikus avatar, életkor","3000 fős panel, életkor"),("Minden avatar MI-modellel „gondolkodik”: válaszol, indokol, vitatkozik.","Minden válaszadó saját élethelyzetből válaszol, indokol, vitatkozik."),("Ez gyors, olcsó <b>szimulált panel</b>, nem valós emberek reprezentatív felmérése.","Ez gyors, megfizethető <b>modellezett panel</b>, nem valós emberek reprezentatív felmérése."),("Az avatarok nem valós, megnevezett személyek, személyes adatot nem használunk.","A válaszadók nem valós, megnevezett személyek; személyes adatot nem használunk."),("Az MI-modellek torzításokat hordozhatnak","A modellek torzításokat hordozhatnak"),("Nem. 3000 szintetikus, MI-alapú avatar válaszol","Nem. Egy 3000 fős, modellezett panel válaszol"),("szimulált hangulatképként","modellezett hangulatképként"),("3000 avatar","3000 válaszadó"),("avatar ","válaszadó ")]
def build(n,t,head,navh,herewrap,th,foot):
  card=t["card"];h2=t["h2"]
  o=head+navh+herewrap(hero(t))
  o+=S("avatarok",t["sb"],"A panel: 3000 hang Magyarországról",avatars(card,t["acc"]),h2,"Kik válaszolnak?")
  o+=S("arak",t["sa"],"Csomagok",tiers(card,t["acc"]),h2,"Válaszd ki, mire van szükséged. Minden ár példa.")
  o+=S("riport",t["sb"],"Mit kapsz? — mintariport",charts(card,REP)+'<div class="mt-6">'+reportpages(card)+'</div>',h2,"Számok, bontások, grafikonok, idézetek és javaslatok. Minden adat Mintaadat.")
  o+=S("kinek",t["sa"],"Kinek való?",uses(card),h2)
  o+=S("utca",t["sb"],"Boltoktól a városházáig",gallery(["zoldseg","sorgyar","bolt","piac","cafe","iroda","debrecen","szeged","eger","sopron","tram","village"],"grid grid-cols-2 md:grid-cols-6 gap-2","h-32"),h2,"Magyar vállalkozások és települések kérdéseire.")
  o+=S("hasonlit",t["sa"],"Hagyományos kutatás vs. magorg.hu",f'<div class="{card}"><div data-chart="cmp"></div></div>',h2)
  o+=S("panel",t["sb"],"A 3000 fős panel — és a korlátai",f'<div class="{card}">{LIM}</div>',h2)
  o+=S("gyik",t["sa"],"Gyakori kérdések",faq2(card),h2)
  o+=f'<section id="kapcsolat" class="{t["cta"]}"><div class="max-w-3xl mx-auto px-5 text-center"><h2 class="{h2}">Tedd fel az első kérdésed még ma.</h2><p class="opacity-80 mt-2">Már 9 900 Ft-tól (példa ár). Gyors, olcsó, szimulált panel.</p><a href="#top" class="inline-block mt-6 {t["btn"]}">Kutatás indítása →</a>'+'<p class="text-xs opacity-60 mt-6">Képek: Wikimedia Commons, szabad licencek — <a class="underline" href="../CREDITS.md">forrásmegjelölés</a>. Minden szám és grafikon <b>mintaadat</b>, az árak <b>példák</b>. Az avatarok szintetikusak, nem valós személyek; az eredmény nem reprezentatív felmérés.</p></div></section>'
  o+=foot+f'<script>const PAL={th.split("p:")[1].split("]")[0]}];</script>'+SC(th)+DEMOJS+'</body></html>'
  o=o.replace('href=#hogyan>Hogyan működik','href=#arak>Csomagok').replace('href=#riport>Mit kapsz','href=#avatarok>Avatarok') if False else o.replace('href=#hogyan>Hogyan működik','href=#arak>Csomagok').replace('href=#panel>Avatar-panel','href=#riport>Mit kapsz').replace('href=#szolg>Szolgáltatások','href=#kinek>Kinek').replace('href=#arak>Árak','href=#panel>Panel')
  o=o.replace('</head>','<link href="https://fonts.googleapis.com/css2?family=Caveat:wght@500&display=swap" rel="stylesheet"><style>.hand{font-family:Caveat,cursive}</style></head>')
  for a,b in REPL: o=o.replace(a,b)
  page(n,o)
